import {libraryTypes,editorLibrary} from './library.js';
import {COURSE,uploads,LIMITS} from './model.js';
import {esc,icon,btn,ibtn,link,field,notice,empty,search} from './ui.js';
const typeLabel=t=>libraryTypes[t]||'Материал';
const labels={ready:'Готово',partial:'Частично прочитан',error:'Ошибка',unsupported:'Не поддерживается',attachment:'Только вложение',checking:'Проверка',extracting:'Извлечение текста'};
export function editorList(s){const savedIds=new Set(s.savedCourses.map(c=>c.id));const pending=Object.values(s.courseWorkspaces||{}).filter(a=>a.name&&!savedIds.has(a.workspaceId)).map(a=>({id:a.workspaceId,name:a.name,published:false}));const rows=[{id:'published',name:COURSE,published:true},...s.savedCourses,...pending];const shown=rows.filter(c=>c.name.toLowerCase().includes(s.search.toLowerCase()));return `<div class="page-head"><h1>Редактор обучения</h1></div><nav class="tabs"><button class="active">Курсы</button><button data-action="editor-articles">Статьи</button></nav><div class="toolbar">${btn(icon('sg-plus')+' Создать курс','create-menu','primary')}${search(s.search,'editor-search','Поиск курса')}<span class="grow"></span><label class="small muted">Статус <select id="editor-filter"><option>Все</option><option>Опубликован</option><option>Черновик</option></select></label></div><div class="table-wrap"><table><thead><tr><th>Название</th><th>Тип</th><th>Статус</th><th></th></tr></thead><tbody>${shown.map(c=>`<tr data-published="${c.published}"><td>${link(esc(c.name),`/editor/courses/${c.id}/lectures`)}<p class="small muted">Клиентский сервис</p></td><td>Онлайн-курс</td><td><span class="status ${c.published?'published':''}">${c.published?'Опубликован':'Черновик'}</span></td><td>${link(icon('arrow-right'),`/editor/courses/${c.id}/lectures`,'icon-btn')}</td></tr>`).join('')}</tbody></table>${shown.length?'':empty('Курсы не найдены','Измените запрос.')}</div>${s.author.groups.length&&!s.author.draftId?`<div class="resume-row">${icon('edit')}<div class="grow"><b>Подготовка нового курса</b><p class="muted small">Ваша структура и правки сохранены</p></div>${btn('Продолжить','resume-author','secondary')}</div>`:''}`;}
export function editor(s,route){const a=s.author;const published=route.includes('/published');const readOnly=published||s.scenario==='rights-lost';const title=published?COURSE:(a.name||'Новый курс');const stage=a.step;const isInfo=route.endsWith('/information')||/^\/editor\/courses\/[^/]+$/.test(route);const atSources=!published&&['sources','structure','generating','review'].includes(stage)&&!route.includes('/settings')&&!(route.endsWith('/information')||/^\/editor\/courses\/[^/]+$/.test(route));
 return `<div class="page-head"><div class="row">${link(icon('arrow-left'),'/editor/courses','icon-btn')}<div><div class="row"><h1>${esc(title)}</h1><span class="status ${published?'published':''}">${published?'Опубликован':'Черновик'}</span></div><p class="small muted">${published?'Онлайн-курс':a.draftId?'Сохранён · доступен только редакторам':'Новый курс · не опубликован'}</p></div></div></div><nav class="tabs">${['Информация','Содержание','Настройки'].map((t,i)=>`<a class="tab-link ${(i===1&&!isInfo&&!route.endsWith('/settings'))||(i===0&&isInfo)||(i===2&&route.endsWith('/settings'))?'active':''}" href="#/editor/courses/${published?'published':a.draftId||a.workspaceId||'new'}${['','/lectures','/settings'][i]}">${t}</a>`).join('')}</nav>${readOnly&& !published?notice('Нет прав на изменение. Ваши локальные правки сохранены.','error'):''}${published?publishedContent():isInfo?`<section class="form-section stack">${field('course-name','Название курса',a.name,{required:true})}${field('description','Описание',a.description,{area:true})}${btn('Сохранить информацию','save-info','primary')}</section>`:route.endsWith('/settings')?`<section class="form-section"><h2>Настройки курса</h2><div class="info-row"><span>Публикация</span><span>Курс не опубликован</span></div><div class="info-row"><span>Назначение сотрудникам</span><span>Не выполнялось</span></div><p class="muted">Сохранение черновика не изменяет видимость материалов.</p></section>`:atSources?authorWork(s):savedContent(s)}${atSources?'':`<footer class="editor-footer"><span class="hint grow">${a.status==='saving'?'Сохраняем…':a.error?esc(a.error):!published?'Черновик не назначается сотрудникам автоматически':''}</span>${link('Выйти','/editor/courses','btn')}${btn('Предпросмотр','preview-course','',!a.draftId&&!published?'disabled':'')}${btn('Опубликовать','publish','',!a.draftId&&!published?'disabled':'')}${btn('Назначить','assign','primary',!published?'disabled title="Сначала опубликуйте курс"':'')}</footer>`}`;
}
function publishedContent(){return `<section class="form-section"><h2>Содержание курса</h2><p class="muted mt">Опубликованный курс. Помощник автора в этой версии работает только с новым курсом.</p>${['Регистрация обращения','Сложные случаи','Материалы','Проверка знаний'].map(t=>`<div class="material-row">${icon('book')}<h3>${t}</h3></div>`).join('')}${link('Открыть курс','/learning/course/101','btn')}</section>`;}
function authorWork(s){const a=s.author;return `<section class="author-work"><div class="row between mb"><h2>${({sources:'Материалы курса',structure:'Проверьте структуру курса',generating:'Подготовка элементов',review:'Проверьте содержание'})[a.step]}</h2><span class="muted small">${({sources:'1 / 3',structure:'2 / 3',generating:'3 / 3',review:'3 / 3'})[a.step]}</span></div><nav class="author-progress"><span>1. Задача и материалы</span><span class="${a.step==='structure'?'current':''}">2. Структура и рекомендации</span><span class="${a.step==='review'?'current':''}">3. Проверка и черновик</span></nav>${a.step==='sources'?sourceForm(s):a.step==='structure'?structure(s):a.step==='generating'?`<div class="loading-work" role="status"><div class="spinner"></div><h3>Подготавливаем выбранные элементы</h3><p class="muted">Структура принята · ${a.blocks.length} элементов</p>${btn('Отменить подготовку','cancel-generation')}</div>`:review(s)}</section>`;}
function sourceForm(s){const a=s.author;const count=a.files.length+(a.selectedLibrary||[]).length;return `<section class="simple-sources"><div class="brief-summary"><div><b>${esc(a.audience||'Укажите аудиторию')}</b><p class="muted mt">${esc(a.objective||'Укажите результат обучения')}</p></div>${a.audience&&a.objective?`<details class="brief-edit"><summary>Изменить задачу</summary><div class="stack mt">${field('course-name','Название',a.name,{required:true})}${field('audience','Для кого курс',a.audience,{required:true})}${field('objective','Чему должны научиться',a.objective,{area:true,required:true})}</div></details>`:''}</div>${!a.audience||!a.objective?`<div class="stack brief-required">${!a.audience?field('audience','Для кого курс',a.audience,{required:true}):''}${!a.objective?field('objective','Чему должны научиться',a.objective,{area:true,required:true}):''}</div>`:''}<div class="row between mt"><h3>Материалы <span class="muted">${count||''}</span></h3>${count?btn('Добавить материал','material-menu','secondary'):''}</div>${count?'':`<div class="materials-empty"><div class="empty-symbol">+</div><h3>Из чего соберём курс?</h3><p class="muted">Загрузите исходники или выберите готовые элементы редактора.</p>${btn('Добавить материал','material-menu','secondary')}<p class="hint">Текст, DOCX, PDF · видео и SCORM по описанию</p></div>`}<div class="file-list">${a.files.map(f=>`<div class="file-row">${icon('attachment')}<div class="grow"><b>${esc(f.name)}</b><p class="hint">${labels[f.status]} · ${esc(f.note)}</p>${['error','unsupported'].includes(f.status)?btn('Заменить файл','replace-file','tertiary',`data-id="${f.id}"`):''}${['MP4','SCORM'].includes(f.format)?`<label class="field mt"><span class="hint">Описание для размещения</span><textarea data-source-description="${f.id}" aria-label="Описание ${esc(f.name)}">${esc(f.description||'')}</textarea></label>`:''}</div>${ibtn('cross-outlined','remove-file','Убрать исходник',`data-id="${f.id}"`)}</div>`).join('')}${(a.selectedLibrary||[]).map(id=>editorLibrary.find(x=>x.id===id)).filter(Boolean).map(x=>`<div class="selected-library">${icon('book')}<div class="grow"><b>${esc(x.name)}</b><p class="hint">${typeLabel(x.type)} · из редактора${['video','scorm'].includes(x.type)?' · по описанию':''}</p></div>${ibtn('cross-outlined','library-remove','Убрать элемент',`data-id="${x.id}"`)}</div>`).join('')}</div><div class="field-error" data-error="files"></div>${a.files.some(f=>f.status==='partial')?`<label class="check mt"><input type="checkbox" id="accept-partial" ${a.acceptedPartial?'checked':''}>Использовать прочитанную часть</label><div class="field-error" data-error="partial"></div>`:''}<div class="work-actions simple-stage-footer">${btn('Собрать вручную','start-outline','tertiary')}<span class="grow"></span>${btn(a.keepOutline?'Дополнить структуру':'Предложить структуру','build-structure','primary')}</div></section>`;}
function structure(s){const a=s.author;return `<div class="outline-toolbar"><div><h3>Содержание курса</h3><p class="hint mt">${a.groups.length} разделов · ${a.blocks.length} элементов</p></div><details class="compact-menu"><summary>Ещё ···</summary><div>${a.groups.length?btn('Добавить раздел','add-group','tertiary'):''}${btn('Исходники и задача','back-sources','tertiary')}</div></details></div><div class="outline-layout"><section class="structure-list">${!a.groups.length?`<div class="outline-empty"><h3>Пока нет разделов</h3><p class="muted mt">Добавьте первый раздел, затем наполните его материалами.</p>${btn('Добавить раздел','add-group','secondary')}</div>`:''}${a.groups.map((g,i)=>`<section class="structure-group"><div class="group-row"><span class="group-number">${i+1}</span><input class="plain-input group-name" aria-label="Название раздела ${i+1}" data-group="${g.id}" value="${esc(g.name)}"><details class="compact-menu"><summary aria-label="Действия с разделом ${i+1}">···</summary><div>${btn('Выше','move-group','tertiary',`data-id="${g.id}"`)}${btn('Ниже','down-group','tertiary',`data-id="${g.id}"`)}${btn('Удалить раздел','remove-group','tertiary',`data-id="${g.id}"`)}</div></details></div>${a.blocks.filter(b=>b.group===g.id).map(b=>`<div class="structure-item" data-element="${b.id}"><button class="element-arrow" data-action="toggle-element" data-id="${b.id}" aria-label="Показать описание ${esc(b.name)}" aria-expanded="${a.expandedElement===b.id}">${a.expandedElement===b.id?'⌄':'›'}</button>${icon(b.type==='file'?'attachment':'book')}<div class="grow"><span class="hint">${typeLabel(b.type)}${b.existing?' · из редактора':''}</span><input class="plain-input" aria-label="Название элемента" data-blockname="${b.id}" value="${esc(b.name)}">${a.expandedElement===b.id?`<p class="element-description">${esc(b.text)}</p>`:''}${b.metadataOnly||['video','scorm'].includes(b.type)?'<p class="hint">По описанию · содержимое не анализировалось</p>':''}</div><details class="compact-menu"><summary aria-label="Действия с ${esc(b.name)}">···</summary><div><label class="field"><span class="hint">Перенести в раздел</span><select data-block-group="${b.id}" aria-label="Раздел для ${esc(b.name)}">${a.groups.map(x=>`<option value="${x.id}" ${x.id===b.group?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>${btn('Выше','up-block','tertiary',`data-id="${b.id}"`)}${btn('Ниже','down-block','tertiary',`data-id="${b.id}"`)}${btn('Убрать из курса','remove-block','tertiary',`data-id="${b.id}"`)}</div></details></div>`).join('')||'<p class="hint empty-group-hint">Добавьте материал в этот раздел</p>'}${btn('+ Добавить элемент','element-menu','tertiary',`data-group="${g.id}"`)}</section>`).join('')}</section>${recommendations(a)}</div><div class="field-error" id="structure-error"></div><div class="work-actions simple-stage-footer"><p class="hint grow">Сначала проверьте структуру. Публикация — после сохранения черновика.</p>${btn('Перейти к проверке','accept-structure','primary')}</div>`;}
function review(s){const a=s.author;return `<p class="muted mb">Проверьте новые тексты. Готовые элементы включаются без изменения содержимого; их размещение уже подтверждено при выборе.</p>${a.blocks.map(b=>`<div class="review-row">${icon(b.type==='file'?'attachment':'book')}<div class="grow"><b>${esc(b.name)}</b><p class="hint">${a.groups.find(g=>g.id===b.group)?.name||''} · ${esc(b.source)}</p></div><span class="status">${b.existing||b.metadataOnly?'Готовый материал':b.accepted?'Проверен':'Проверьте текст'}</span>${link(b.existing||b.metadataOnly?'Посмотреть':'Проверить текст',`/editor/articles/${b.id}`,'btn')}</div>`).join('')}<div class="work-actions">${btn('К структуре','back-structure')}${btn('Сохранить черновик','save-draft','primary',a.status==='saving'?'disabled':'')}</div>${a.error?notice(esc(a.error),'error'):''}`;}
function savedContent(s){const a=s.author;return `<section class="author-work"><div class="row between mb"><h2>Содержание курса</h2>${btn('Добавить элемент','add-manual-element','secondary')}</div>${a.draftId?notice('Черновик сохранён. Статьи можно редактировать, курс ещё не опубликован.'):''}${a.groups.map(g=>`<h3 class="mt">${esc(g.name)}</h3>${a.blocks.filter(b=>b.group===g.id).map(b=>`<div class="review-row">${icon(b.type==='file'?'attachment':'book')}<div class="grow">${link(esc(b.name),`/editor/articles/${b.id}`)}<p class="hint">${typeLabel(b.type)} · ${b.url?'Со ссылкой на материал':'Редактируемый элемент'}</p></div>${link(icon('edit'),`/editor/articles/${b.id}`,'icon-btn')}</div>`).join('')}`).join('')||empty('В курсе пока нет элементов','Добавьте статью или подготовьте содержание из материалов.',btn('Подготовить с ИИ','resume-author','secondary'))}${a.blocks.length?`<div class="work-actions">${btn('Сохранить черновик','save-draft','primary',a.status==='saving'?'disabled':'')}</div>`:''}</section>`;}
export function articleEditor(s,id){const a=s.author;const b=a.blocks.find(x=>x.id===id);if(!b)return empty('Элемент не найден','Вернитесь к содержанию курса.',link('К содержанию','/editor/courses/new/lectures'));if(b.existing)return `<div class="page-head"><h1>${esc(b.name)}</h1><span class="tag">${typeLabel(b.type)}</span></div><section class="article-editor stack"><h2>Готовый элемент редактора</h2><p>${esc(b.text)}</p>${notice(['test','survey'].includes(b.type)?'Вопросы, ответы и настройки остаются без изменений. Помощник определяет только место элемента в курсе.':['video','scorm'].includes(b.type)?'Используем название и описание. Содержимое не анализировалось.':'Используем существующий материал. Его содержание не изменяется.')}<p>Раздел: <b>${esc(a.groups.find(g=>g.id===b.group)?.name||'')}</b></p><p class="hint">${esc(b.reason||'Размещение выбрано автором')}</p><div class="work-actions">${link('К структуре',`/editor/courses/${a.draftId||a.workspaceId||'new'}/lectures`,'btn')}</div></section>`;return `<div class="page-head"><div class="row">${link(icon('arrow-left'),`/editor/courses/${a.draftId||a.workspaceId||'new'}/lectures`,'icon-btn')}<div><h1>${b.type!=='article'?'Материал':'Редактор статьи'}</h1><p class="muted small">${esc(a.name)}</p></div></div><span class="status">${b.accepted?'Принят':'На проверке'}</span></div><section class="article-editor stack">${field('block-name','Название',b.name,{required:true})}<div class="field"><label for="block-text">${b.type!=='article'?'Описание материала':'Содержание'} <span class="required">*</span></label><div class="rich"><div class="rich-tools"><span>Текст</span><span class="muted">·</span><span>Абзац</span></div><textarea id="block-text" aria-label="Содержание статьи">${esc(b.text)}</textarea></div><div class="field-error" data-error="block-text"></div></div><p class="hint">Источник: ${esc(b.source)}${b.url?' · Содержимое сайта не анализировалось':''}</p>${b.url?link('Проверить ссылку',b.url,'link'):''}${a.proposal?.id===id?`<section class="proposal"><h2>Предложенная версия</h2><p class="muted small">Ваш текст выше сохранён. Замена произойдёт только после подтверждения.</p><p class="proposed-text">${esc(a.proposal.text)}</p><div class="row">${btn('Оставить текущий текст','keep-text')}${btn('Применить предложение','apply-proposal','primary')}</div></section>`:''}${a.error?notice(esc(a.error),'error'):''}<div class="work-actions">${btn('Предложить новую версию','regenerate','secondary',b.type!=='article'?'disabled title="Файл не генерируется заново"':'')}${btn(a.draftId?'Сохранить правки':'Принять элемент','accept-block','primary')}</div></section>`;}
export function filePicker(s){return `<p class="muted mb">Выберите демонстрационные исходники. Реальные файлы никуда не отправляются.</p>${uploads.map(f=>`<label class="pick-row"><input type="checkbox" name="source-file" value="${f.id}" ${s.author.files.some(x=>x.id===f.id)?'checked':''}><div><b>${f.name}</b><p class="hint">${f.format} · ${f.note}</p></div></label>`).join('')}`;}

function recommendations(a){const all=[
{id:'intro',missing:!a.blocks.some(b=>b.type==='article'),title:'Объяснение перед практикой',text:'Добавьте вводную статью, чтобы дать основу перед упражнениями.',label:'Добавить статью'},
{id:'practice',missing:!a.blocks.some(b=>['task','scorm'].includes(b.type)),title:'Не хватает практики',text:'Задание поможет применить изученное.',label:'Добавить практику'},
{id:'check',missing:!a.blocks.some(b=>b.type==='test'),title:'Проверка результата',text:'Готовый тест можно поставить после учебной части.',label:'Добавить тест'},
{id:'feedback',missing:!a.blocks.some(b=>b.type==='survey'),title:'Обратная связь',text:'Опрос поможет узнать, что было полезно и что осталось непонятным.',label:'Добавить опрос'}
].filter(x=>x.missing&&!(a.dismissedRecommendations||[]).includes(x.id));return `<aside class="course-recommendations"><span class="ai-label">✦ Skillaz AI</span><h3>Что можно улучшить</h3><p class="hint mt">Необязательно. Добавляйте только то, что нужно вашему курсу.</p>${all.length?all.map(r=>`<section class="recommendation" data-recommendation="${r.id}"><div class="row between"><b>${r.title}</b><details class="compact-menu"><summary aria-label="Скрыть рекомендацию">···</summary><div>${btn('Пропустить','dismiss-recommendation','tertiary',`data-id="${r.id}"`)}</div></details></div><p class="small muted">${r.text}</p>${btn(r.label,'recommend-library','secondary',`data-id="${r.id}"`)}</section>`).join(''):'<p class="small muted mt">Всё добавлено или пропущено. Финальное решение о составе курса — за вами.</p>'}${a.blocks.some(b=>['video','scorm'].includes(b.type))?'<p class="hint metadata-note">Видео и SCORM размещены по описанию. Проверьте содержимое перед публикацией.</p>':''}</aside>`;}
